  "plan": "Preparar uma conta Data no PDA canonico derivado de [key.to_le_bytes(), bump_canonico] e chamar set_value legitimamente com o bump canonico para provar que o cenario esta correto. Em seguida, atacar chamando set_value com um bump nao canonico que gera um endereco off-curve diferente, passando uma conta Data controlada nesse endereco alternativo. O efeito medido e que o value da conta alternativa foi alterado, demonstrando que o programa aceitou um PDA nao canonico.",
  "scenario": "let key: u64 = 42;
let new_value: u64 = 999;

// Deriva o PDA canonico
let (canonical_pda, canonical_bump) = Pubkey::find_program_address(&[key.to_le_bytes().as_ref()], &env.program_id);

// Conta Data canonica com value inicial 0
let data_account = account(&env.program_id, &anchor_account_data("Data", &(0u64,)), None);

// Baseline: chamada legitima com bump canonico
let ix_baseline = env.anchor_ix("set_value", &(key, new_value, canonical_bump), vec![
    AccountMeta::new(canonical_pda, false),
]);
let contas_baseline = vec![
    (canonical_pda, data_account.clone()),
];
let r_baseline = env.baseline("set_value legitimo com bump canonico", &ix_baseline, &contas_baseline);

